// @id: infinite-loop
// @title: Infinite loop
// @expect: Time Limit Exceeded
// @sr: SR-7, SR-5
// @summary: Spins forever at 100% CPU. The wall-clock limit must kill it, and the CPU quota keeps the host responsive meanwhile.
#include <cstdio>

int main() {
    std::puts("Spinning forever... try and stop me.");
    std::fflush(stdout);
    volatile unsigned long long n = 0;
    while (true) { n++; }
}

// @id: output-flood
// @title: Endless output
// @expect: Output Limit Exceeded
// @sr: SR-11
// @summary: Prints forever as fast as possible. Output is capped, the process is killed, and the platform stays healthy.
#include <cstdio>

int main() {
    for (unsigned long long i = 0;; i++) {
        std::printf("line %llu: AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA\n", i);
    }
}
